/**
 * The seeded demo listing set: a small catalogue a judge can browse on /listings without uploading
 * anything, and the deliberately bad flat-lay that is never listed, with the retake made from it.
 *
 *   demo-tee     Rust T-shirt — the seeded retake of the bad flat-lay (lib/readiness/seeded.ts)
 *   demo-jumper  Teal jumper  — laid flat on a plain sheet in even light (drawn below)
 *   demo-shirt   Navy shirt   — plain sheet, light fading towards one corner (drawn below)
 *
 * Every picture is a DRAWING generated by code written for this project, not a photograph, so the
 * project owns it and it is released under the repository's MIT licence. No photograph, stock or
 * marketplace image, brand, logo or person is involved. Each picture has a row in the asset register
 * (PROVENANCE.md, section 2), and the same facts are shown on its listing page.
 *
 * Nothing about a grade is written here. Each picture is graded at run time by the same code as a
 * seller's photo, and a picture that is not accepted is not listed. Server-only: it renders pixels.
 */

import { analyseFlatLay } from "@/lib/readiness/analyse";
import type { PixelGrid } from "@/lib/readiness/contracts";
import { gradeReadiness } from "@/lib/readiness/grade";
import { SEEDED_FIXTURE_SIZE, rasteriseScene, renderSeededFixture, seededFixtureInfo } from "@/lib/readiness/seeded";

import { findCategory } from "./categories";
import { listingReadiness, type ImageProvenance, type PublishedListing, type RejectedFirstAttempt } from "./contracts";

/** Where the bad flat-lay and its retake run through the readiness checks with no upload. */
export const SEEDED_REPRODUCE_URL = "/sell/new#seeded-heading";

const DRAWING_AUTHOR =
  "Drawn pixel by pixel by code written for this project. Not a photograph: no real garment, person, brand or third-party image is shown.";
const LICENCE = "MIT, the repository licence (LICENSE)";
const REGISTER = "PROVENANCE.md, section 2";

/** The bad flat-lay and the retake, drawn by lib/readiness/seeded.ts. */
export const SEEDED_FIXTURE_PROVENANCE: ImageProvenance = {
  kind: "drawing",
  author: DRAWING_AUTHOR,
  madeBy: "lib/readiness/seeded.ts",
  licence: LICENCE,
  register: REGISTER,
};

const SET_PROVENANCE: ImageProvenance = { ...SEEDED_FIXTURE_PROVENANCE, madeBy: "lib/listings/seeded-set.ts" };

// ---------------------------------------------------------------------------
// Drawings
// ---------------------------------------------------------------------------

export type SeededDrawingName = "jumper" | "shirt";

export const SEEDED_DRAWING_NAMES: readonly SeededDrawingName[] = ["jumper", "shirt"];

export function isSeededDrawingName(value: string): value is SeededDrawingName {
  return (SEEDED_DRAWING_NAMES as readonly string[]).includes(value);
}

type Rgb = readonly [number, number, number];
type Outline = ReadonlyArray<readonly [number, number]>;

function insideOutline(outline: Outline, u: number, v: number): boolean {
  let inside = false;
  for (let i = 0, j = outline.length - 1; i < outline.length; j = i++) {
    const [ui, vi] = outline[i];
    const [uj, vj] = outline[j];
    if (vi > v !== vj > v && u < ((uj - ui) * (v - vi)) / (vj - vi) + ui) inside = !inside;
  }
  return inside;
}

function scale(c: Rgb, k: number): Rgb {
  return [c[0] * k, c[1] * k, c[2] * k];
}

/** Both garments lie flat and straight in this box of the frame; outlines are 0–1 inside it. */
const BOX = { x: 70, y: 105, width: 340, height: 430 } as const;

/** Share of the frame diagonal from the top-left corner, 0–1. Drives the light fall-off. */
function diagonal(fx: number, fy: number): number {
  return 0.5 * (fx / SEEDED_FIXTURE_SIZE.width) + 0.5 * (fy / SEEDED_FIXTURE_SIZE.height);
}

/** Long-sleeved body shape shared by both garments, sleeves angled down beside the body. */
const LONG_SLEEVE_OUTLINE: Outline = [
  [0.3, 0.0],
  [0.7, 0.0],
  [0.91, 0.09],
  [1.0, 0.61],
  [0.87, 0.64],
  [0.79, 0.29],
  [0.79, 1.0],
  [0.21, 1.0],
  [0.21, 0.29],
  [0.13, 0.64],
  [0.0, 0.61],
  [0.09, 0.09],
];

const JUMPER: Rgb = [46, 122, 124];
const JUMPER_SHEET: Rgb = [212, 206, 196];

/** Teal crew-neck jumper on a plain warm grey sheet, even light. */
function sampleJumper(fx: number, fy: number): Rgb {
  const light = 1 - 0.04 * diagonal(fx, fy);
  const u = (fx - BOX.x) / BOX.width;
  const v = (fy - BOX.y) / BOX.height;
  if (!insideOutline(LONG_SLEEVE_OUTLINE, u, v)) return scale(JUMPER_SHEET, light);

  const du = (u - 0.5) / 0.13;
  const dv = v / 0.06;
  let shade = 1;
  if (du * du + dv * dv < 1) shade = 0.72; // inside of the neck
  else if (v > 0.91 || (v > 0.54 && (u < 0.2 || u > 0.8))) shade = 0.9; // ribbed hem and cuffs
  return scale(JUMPER, light * shade);
}

const SHIRT: Rgb = [44, 58, 96];
const SHIRT_SHEET: Rgb = [228, 226, 220];
/**
 * Daylight from the top left: the far corner of the sheet is about a third darker. Chosen so the
 * occlusion/shadow check lands on a warning rather than a pass or a fail, which gives the set a
 * grade B listing; the build output (/api/listings/seeded) shows the score it actually gets.
 */
const SHIRT_FALLOFF = 0.37;
const SHIRT_COLLAR: readonly Outline[] = [
  [
    [0.3, 0.0],
    [0.5, 0.07],
    [0.4, 0.14],
  ],
  [
    [0.7, 0.0],
    [0.5, 0.07],
    [0.6, 0.14],
  ],
];
const SHIRT_BUTTONS_V = [0.18, 0.34, 0.5, 0.66, 0.82] as const;

/** Navy button-up shirt on a plain pale sheet, light fading towards the lower right. */
function sampleShirt(fx: number, fy: number): Rgb {
  const light = 1 - SHIRT_FALLOFF * diagonal(fx, fy);
  const u = (fx - BOX.x) / BOX.width;
  const v = (fy - BOX.y) / BOX.height;
  if (!insideOutline(LONG_SLEEVE_OUTLINE, u, v)) return scale(SHIRT_SHEET, light);

  let shade = 1;
  if (SHIRT_COLLAR.some((tri) => insideOutline(tri, u, v))) shade = 0.8;
  else if (SHIRT_BUTTONS_V.some((bv) => Math.hypot((u - 0.5) * BOX.width, (v - bv) * BOX.height) < 4)) shade = 1.3;
  else if (Math.abs(u - 0.5) < 0.016 && v > 0.07) shade = 1.12; // button placket
  return scale(SHIRT, light * shade);
}

const drawn = new Map<SeededDrawingName, PixelGrid>();

/** Renders a drawing of the set to RGBA pixels. Deterministic; memoised per process. */
export function renderSeededDrawing(name: SeededDrawingName): PixelGrid {
  const cached = drawn.get(name);
  if (cached) return cached;
  const grid = rasteriseScene(name === "jumper" ? sampleJumper : sampleShirt);
  drawn.set(name, grid);
  return grid;
}

// ---------------------------------------------------------------------------
// Catalogue
// ---------------------------------------------------------------------------

interface SetEntry {
  id: string;
  title: string;
  category: string;
  image: NonNullable<PublishedListing["image"]>;
  provenance: ImageProvenance;
  pixels: () => PixelGrid;
  /** True for the listing made from the retake of the seeded bad flat-lay. */
  isRetake: boolean;
}

function drawingImage(name: SeededDrawingName, alt: string): SetEntry["image"] {
  return { url: `/api/listings/seeded/${name}`, alt, ...SEEDED_FIXTURE_SIZE };
}

function fixtureImage(name: "bad" | "retake"): SetEntry["image"] {
  const info = seededFixtureInfo(name);
  return { url: info.imageUrl, alt: info.alt, width: info.width, height: info.height };
}

const SET: readonly SetEntry[] = [
  {
    id: "demo-tee",
    title: "Rust T-shirt",
    category: "tops",
    image: fixtureImage("retake"),
    provenance: SEEDED_FIXTURE_PROVENANCE,
    pixels: () => renderSeededFixture("retake"),
    isRetake: true,
  },
  {
    id: "demo-jumper",
    title: "Teal crew-neck jumper",
    category: "knitwear",
    image: drawingImage(
      "jumper",
      "Drawing of a teal long-sleeved crew-neck jumper laid flat and straight on a plain warm grey sheet in even light.",
    ),
    provenance: SET_PROVENANCE,
    pixels: () => renderSeededDrawing("jumper"),
    isRetake: false,
  },
  {
    id: "demo-shirt",
    title: "Navy button-up shirt",
    category: "shirts",
    image: drawingImage(
      "shirt",
      "Drawing of a navy long-sleeved button-up shirt laid flat on a plain pale sheet, with the light fading towards the lower right corner.",
    ),
    provenance: SET_PROVENANCE,
    pixels: () => renderSeededDrawing("shirt"),
    isRetake: false,
  },
];

let rejection: RejectedFirstAttempt | null | undefined;

/**
 * The seeded bad flat-lay as a refused first attempt, graded by the same code as any photo. Null
 * if the current thresholds were ever to accept it, so a page never shows a rejection that the
 * checks would not reproduce.
 */
export function seededRejection(): RejectedFirstAttempt | null {
  if (rejection !== undefined) return rejection;
  const result = analyseFlatLay(renderSeededFixture("bad"));
  const graded = gradeReadiness(result);
  rejection =
    !result.accepted && graded
      ? {
          title: seededFixtureInfo("bad").title,
          image: fixtureImage("bad"),
          provenance: SEEDED_FIXTURE_PROVENANCE,
          readiness: listingReadiness(graded, result.checks, result.thresholdVersion),
          instructions: result.instructions.map((ins) => ins.title),
          reproduceUrl: SEEDED_REPRODUCE_URL,
        }
      : null;
  return rejection;
}

let listings: PublishedListing[] | undefined;

/** The listings of the seeded set that the current checks accept, in catalogue order. */
export function seededDemoListings(): PublishedListing[] {
  if (listings) return listings;
  listings = [];
  for (const entry of SET) {
    const result = analyseFlatLay(entry.pixels());
    const graded = gradeReadiness(result);
    const category = findCategory(entry.category);
    if (!result.accepted || !graded || graded.grade === "C" || !category || category.blocked) continue;
    listings.push({
      id: entry.id,
      title: entry.title,
      category: category.id,
      categoryLabel: category.label,
      sizeText: null,
      status: "published",
      isDemo: true,
      image: entry.image,
      provenance: entry.provenance,
      retakeOf: entry.isRetake ? seededRejection() : null,
      readiness: listingReadiness(graded, result.checks, result.thresholdVersion),
      publishedAt: null,
    });
  }
  return listings;
}

/** Every picture of the set, listed or not, with its licence: the in-product asset register. */
export function seededSetAssets(): Array<{ title: string; url: string; provenance: ImageProvenance }> {
  return [
    { title: seededFixtureInfo("bad").title, url: fixtureImage("bad").url, provenance: SEEDED_FIXTURE_PROVENANCE },
    ...SET.map((e) => ({ title: e.title, url: e.image.url, provenance: e.provenance })),
  ];
}
